mapper.select:
SELECT f.id as id, f.vloger_id as vlogerId, vloger.nickname as vlogerNickname, vloger.face as vlogerFace, f.fan_id as fanId, fan.nickname as fanNickname, fan.face as fanFace, f.is_fan_friend_of_mine as isFanFriendOfMine FROM fans f LEFT JOIN users vloger ON f.vloger_id = vloger.id LEFT JOIN users fan ON f.fan_id = fan.id
f.vloger_id = #{paramMap.myId}
ORDER BY f.id DESC
